	/**
	 * Default Constructor
	 */
    public ProductService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ProductEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ProductRepository.class) );
		this.validator		= applicationContext.getBean(ProductValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Product
	 */
		public Product createProduct( CreateProductCommand command ) {

		Product entity = new Product();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setProductId( command.getProductId() );
            entity.setSku( command.getSku() );
            entity.setName( command.getName() );
            entity.setAsActive( command.getAsActive() );
            entity.setStandardPrice( command.getStandardPrice() );
            entity.setDescription( command.getDescription() );
            entity.setProductType( command.getProductType() );
            entity.setUom( command.getUom() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Product {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateProductCommand
	 * @return		Product
	 */
	public Product updateProduct( UpdateProductCommand command ) {

		Product entity = new Product();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setProductId( command.getProductId() );
            entity.setSku( command.getSku() );
            entity.setName( command.getName() );
            entity.setAsActive( command.getAsActive() );
            entity.setStandardPrice( command.getStandardPrice() );
            entity.setDescription( command.getDescription() );
            entity.setOrganization( command.getOrganization() );
            entity.setPriceBookEntries( command.getPriceBookEntries() );
            entity.setOpportunityLineItems( command.getOpportunityLineItems() );
            entity.setQuoteLineItems( command.getQuoteLineItems() );
            entity.setOrderItems( command.getOrderItems() );
            entity.setProductType( command.getProductType() );
            entity.setUom( command.getUom() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Product {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteProductCommand
	 */
	public void delete( DeleteProductCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getProductId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Product {0} ", id );

	}

	/**
	 * Method to retrieve the Product via ProductFetchOneSummary
	 * @param 	summary ProductFetchOneSummary
	 * @return 	ProductFetchOneResponse
	 */
	public Product getProduct( ProductFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ProductFetchOneSummary arg cannot be null" );

		Product entity = null;
		UUID id = summary.getProductId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Product using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Products
	 *
	 * @return 	List<Product>
	 */
    public List<Product> getAllProduct() {
		List<Product> list = projector.findAll( new FindAllProductQuery() );
		return list;
	}

	/**
	 * assign Organization on Product
	 * @param		command AssignOrganizationToProductCommand
	 */
	public void assignOrganization( AssignOrganizationToProductCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getProductId(), command.getAssignment());

	}

